def card(c):
 spark=''
 if c['spark']:
  v,w=c['spark'];a,b=c['spark_names']
  spark=f'<div class="track" role="img" aria-label="{ESC(a)} {v}%、{ESC(b)} {w}%"><i style="width:{v}%"></i><i style="width:{w}%"></i></div><div class="legend"><span>{ESC(a)} {v}%</span><span>{ESC(b)} {w}%</span></div>'
 return f'''<a class="company" href="{ESC(c['href'])}" data-industry="{ESC(c['industry'])}" data-search="{ESC(c['name']+' '+c['code']+' '+c['industry']+' '+c['sub'])}" aria-label="阅读{ESC(c['name'])}2026H1完整独立财务研究">
  <div class="card-head"><span class="ticker">{ESC(c['code'])}.{ESC(c['exchange'])}</span><span class="card-cat">{ESC(c['sub'])}</span></div>
  <h2 class="name">{ESC(c['name'])}</h2><h3>{ESC(c['story'])}</h3><p class="deck">{ESC(c['deck'])}</p>
  <div class="card-viz"><div class="figure-k">{ESC(c['signal_label'])}</div><div class="major">{ESC(c['signal'])}</div>{spark}</div>
  <div class="card-note">2026H1 · {ESC(c['note'])}</div><div class="card-foot"><span>进入独立研究全文 · 原始证据与反证</span><span aria-hidden="true">↗</span></div>
 </a>'''
